307			first.Now, first.NextRetry = 2000, 3000
308			second := waitingRecoveryRecord(kindResult)
309			second.Now, second.Attempts, second.NextRetry = 1000, 2, 3000
310			entries := append(waitingRecoveryBase(), first, second)
311			assertRecoveryCorrupt(t, entries, "result time 1000 before prior time 2000", `"w"`)
312		})
313	}
314	
315	// Compacted snapshot records keep their own acceptance: unknown target and a
316	// repeated snapshot are rejected, zero attempts are rejected, but a snapshot
317	// may restore an attempt count greater than one directly.
318	func TestStateSpecificAcceptance(t *testing.T) {
319		t.Run("unknown id", func(t *testing.T) {
320			entries := []*logEntry{
321				{T: kindState, Now: 1000, ID: "ghost", Status: StatusExpired, Reason: "x", Attempts: 1},
322			}
323			assertRecoveryCorrupt(t, entries, "state for unknown id", `"ghost"`)
324		})
325	
326		t.Run("duplicate snapshot", func(t *testing.T) {
327			entries := append(waitingRecoveryBase(), waitingRecoveryRecord(kindState))
328			entries = append(entries, waitingRecoveryRecord(kindState))
329			assertRecoveryCorrupt(t, entries, "duplicate state for id", `"w"`)
330		})
331	
332		t.Run("zero attempts", func(t *testing.T) {
333			r := terminalRecoveryRecord(kindState)
334			r.Attempts = 0
335			entries := append(terminalRecoveryBase(), r)
336			assertRecoveryCorrupt(t, entries, "state with zero attempts", `"t"`)
337		})
338	}
339	
340	// A snapshot may restore the full current status after more than one attempt,
341	// for both waiting and successful messages; the restored record then behaves
342	// exactly like one that had gone through those attempts live.
343	func TestStateRestoresMultiAttemptStatus(t *testing.T) {
344		t.Run("waiting after three attempts", func(t *testing.T) {
345			dir := t.TempDir()
346			entries := append(waitingRecoveryBase(),
347				&logEntry{
348					T: kindState, Now: 2000, ID: "w", Status: StatusWaiting,
349					Reason:   "waiting for trusted header covering height 100 (current 0)",
350					Attempts: 3, NextRetry: 6000,
351				},
352				&logEntry{T: kindAdvance, Now: 2000},
353			)
354			writeLegacyLog(t, dir, entries...)
355			q, err := Open(dir)
356			if err != nil {
357				t.Fatalf("multi-attempt waiting snapshot must open: %v", err)
358			}
359			r := statusOf(t, q, "w")
360			if r.Status != StatusWaiting || r.Attempts != 3 || r.NextRetry != 6000 {
361				t.Fatalf("snapshot not restored: %+v", r)
362			}
363			if q.Now() != 2000 || len(q.order) != 1 || q.order[0] != "w" {
364				t.Fatalf("time/order not restored: now=%d order=%v", q.Now(), q.order)
365			}
366			// At the scheduled retry the message takes exactly one more attempt;
367			// the fourth backoff interval is 8s, so the next retry is 14000.
368			if _, err := q.Advance(6000); err != nil {
369				t.Fatal(err)
370			}
371			r = statusOf(t, q, "w")
372			if r.Status != StatusWaiting || r.Attempts != 4 || r.NextRetry != 14000 {
373				t.Fatalf("restored waiting record did not continue normally: %+v", r)
374			}
375			if err := q.Close(); err != nil {
376				t.Fatal(err)
377			}
378			q2, err := Open(dir)
379			if err != nil {
380				t.Fatal(err)
381			}
382			defer q2.Close()
383			if r := statusOf(t, q2, "w"); r.Attempts != 4 || r.NextRetry != 14000 || r.Status != StatusWaiting {
384				t.Fatalf("advanced state lost on reopen: %+v", r)
385			}
386		})
387	
388		t.Run("success after five attempts", func(t *testing.T) {
389			dir := t.TempDir()
390			entries := append(successRecoveryBase(),
391				&logEntry{
392					T: kindState, Now: 4000, ID: "m", Status: StatusSuccess,
393					Reason:   "delivered; proof verified by trusted header at height 100",
394					Attempts: 5, ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1, ConsumeBy: "m",
395				},
396				&logEntry{T: kindAdvance, Now: 4000},
397			)
398			writeLegacyLog(t, dir, entries...)
399			q, err := Open(dir)
400			if err != nil {
401				t.Fatalf("multi-attempt success snapshot must open: %v", err)
402			}
403			defer q.Close()
404			r := statusOf(t, q, "m")
405			if r.Status != StatusSuccess || r.Attempts != 5 || r.NextRetry != 0 {
406				t.Fatalf("success snapshot not restored: %+v", r)
407			}
408			if winner := q.consumed[newConsumeToken("a", "b", 1)]; winner != "m" {
409				t.Fatalf("consumption not restored and attributed to m: %q", winner)
410			}
411			// The consumed triple keeps replaying for new ids after restore.
412			if _, err := q.Submit(env("d", "a", "b", 1, 10, 0)); err != nil {
413				t.Fatal(err)
414			}
415			rep, err := q.Advance(5000)
416			if err != nil {
417				t.Fatal(err)
418			}
419			res, ok := resultFor(rep, "d")
420			if !ok || res.Status != StatusReplay || !strings.Contains(res.Reason, "m") {
421				t.Fatalf("restored consumption must keep replaying: %+v", rep.Results)
422			}
423		})
424	
425		t.Run("terminal statuses restored", func(t *testing.T) {
426			dir := t.TempDir()
427			entries := []*logEntry{
428				{T: kindSource, Chain: "a"},
429				{T: kindSubmit, Seq: 0, ID: "r", From: "a", To: "b", Nonce: 1, ProofAt: 10},
430				{T: kindState, Now: 1000, ID: "r", Status: StatusReplay,
431					Reason: "nonce combination already consumed by message z", Attempts: 2},
432				{T: kindSubmit, Seq: 1, ID: "x", From: "a", To: "b", Nonce: 2, ProofAt: 10, ExpiresAt: 1000},
433				{T: kindState, Now: 1000, ID: "x", Status: StatusExpired,
434					Reason: "expired at 1000", Attempts: 1},
435				{T: kindSubmit, Seq: 2, ID: "u", From: "mars", To: "b", Nonce: 3, ProofAt: 10},
436				{T: kindState, Now: 1000, ID: "u", Status: StatusUnknownSrc,
437					Reason: "unknown source chain mars", Attempts: 1},
438				{T: kindAdvance, Now: 1000},
439			}
440			writeLegacyLog(t, dir, entries...)
441			q, err := Open(dir)
442			if err != nil {
443				t.Fatalf("terminal snapshots must open: %v", err)
444			}
445			defer q.Close()
446			want := map[string]string{"r": StatusReplay, "x": StatusExpired, "u": StatusUnknownSrc}
447			for id, st := range want {
448				if r := statusOf(t, q, id); r.Status != st || r.NextRetry != 0 {
449					t.Fatalf("%s snapshot not restored as %s: %+v", id, st, r)
450				}
451			}
452			if r := statusOf(t, q, "r"); r.Attempts != 2 || !strings.Contains(r.Reason, "message z") {
453				t.Fatalf("replay attempts/reason not restored: %+v", r)
454			}
455			if len(q.order) != 0 {
456				t.Fatalf("all snapshot records are terminal, order must be empty: %v", q.order)
457			}
458			all := q.Queries()
459			if len(all) != 3 || all[0].ID != "r" || all[1].ID != "x" || all[2].ID != "u" {
460				t.Fatalf("submission order not preserved: %+v", all)
461			}
462		})
463	}
464	
465	// The shared waiting-schedule rule treats a compacted snapshot exactly like a
466	// plain result near the ceiling: only the exact legacy additive-overflow
467	// value is accepted and repaired to the ceiling in memory; any other wrong
468	// time is corrupt.
469	func TestStateWaitingScheduleCeilingParity(t *testing.T) {
470		t.Run("legacy overflow repaired", func(t *testing.T) {
471			dir := t.TempDir()
472			wrapped := ceiling + nextRetryDelay(2) // old build: raw now+delay
473			if wrapped >= 0 {
474				t.Fatalf("test setup: expected negative wrapped value, got %d", wrapped)
475			}
476			entries := []*logEntry{
477				{T: kindSource, Chain: "a"},
478				{T: kindSubmit, Seq: 0, ID: "w", From: "a", To: "b", Nonce: 7, ProofAt: 100},
479				{T: kindState, Now: ceiling, ID: "w", Status: StatusWaiting,
480					Reason: "waiting", Attempts: 2, NextRetry: wrapped},
481				{T: kindAdvance, Now: ceiling},
482			}
483			writeLegacyLog(t, dir, entries...)
484			q, err := Open(dir)
485			if err != nil {
486				t.Fatalf("legacy overflowed state schedule must open and repair: %v", err)
487			}
488			defer q.Close()
489			if r := statusOf(t, q, "w"); r.Status != StatusWaiting || r.Attempts != 2 || r.NextRetry != ceiling {
490				t.Fatalf("overflowed state schedule not repaired to ceiling: %+v", r)
491			}
492		})
493	
494		t.Run("arbitrary wrong time rejected", func(t *testing.T) {
495			entries := []*logEntry{
496				{T: kindSource, Chain: "a"},
497				{T: kindSubmit, Seq: 0, ID: "w", From: "a", To: "b", Nonce: 7, ProofAt: 100},
498				{T: kindState, Now: ceiling, ID: "w", Status: StatusWaiting,
499					Reason: "waiting", Attempts: 2, NextRetry: ceiling - 1},
500			}
501			assertRecoveryCorrupt(t, entries, "waiting state has wrong retry schedule", `"w"`)
502		})
503	}
504	
505	// Successful recovery leaves the on-disk log untouched and a legitimate
506	// historical directory needs no conversion before further use: a plain-result
507	// log and a compacted log both reopen, preserve content/status/reason/
508	// attempts/retry, and accept new operations afterwards.
509	func TestBothKindsReopenWithoutConversion(t *testing.T) {
510		for _, kind := range []string{kindResult, kindState} {
511			t.Run(kind, func(t *testing.T) {
512				dir := t.TempDir()
513				waiting := &logEntry{
514					T: kind, Now: 1000, ID: "w", Status: StatusWaiting,
515					Reason:   "waiting for trusted header covering height 100 (current 0)",
516					Attempts: 1, NextRetry: 2000,
517				}
518				entries := append(waitingRecoveryBase(), waiting, &logEntry{T: kindAdvance, Now: 1000})
519				path := writeLegacyLog(t, dir, entries...)
520				before, err := os.ReadFile(path)
521				if err != nil {
522					t.Fatal(err)
523				}
524				q, err := Open(dir)
525				if err != nil {
526					t.Fatalf("legitimate %s log must open without conversion: %v", kind, err)
527				}
528				after, err := os.ReadFile(path)
529				if err != nil {
530					t.Fatal(err)
531				}
532				if string(after) != string(before) {
533					t.Fatalf("opening a good %s log rewrote it", kind)
534				}
535				r := statusOf(t, q, "w")
536				if r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != 2000 ||
537					!strings.Contains(r.Reason, "height 100") {
538					t.Fatalf("recovered record mismatch: %+v", r)
539				}
540				// Continuing without any migration step.
541				if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
542					t.Fatal(err)
543				}
544				if _, err := q.Advance(2000); err != nil {
545					t.Fatal(err)
546				}
547				if r := statusOf(t, q, "w"); r.Status != StatusSuccess || r.Attempts != 2 {
548					t.Fatalf("recovered message did not deliver on retry: %+v", r)
549				}
550				if winner := q.consumed[newConsumeToken("a", "b", 7)]; winner != "w" {
551					t.Fatalf("success not attributed to w after recovery: %q", winner)
552				}
553				q.Close()
554			})
555		}
556	}
557	
558	// Guard against the helper itself drifting: the good fixtures must open.
559	func TestRecoveryFixturesAreValid(t *testing.T) {
560		for _, kind := range []string{kindResult, kindState} {
561			dir := t.TempDir()
562			entries := append(successRecoveryBase(), successRecoveryRecord(kind))
563			entries = append(entries, &logEntry{T: kindAdvance, Now: 1000})
564			writeLegacyLog(t, dir, entries...)
565			q, err := Open(dir)
566			if err != nil {
567				t.Fatalf("valid %s success fixture must open: %v", kind, err)
568			}
569			if r := statusOf(t, q, "m"); r.Status != StatusSuccess || r.Attempts != 1 {
570				t.Fatalf("valid %s fixture restored wrong: %+v", kind, r)
571			}
572			q.Close()
573	
574			dir2 := t.TempDir()
575			entries2 := append(terminalRecoveryBase(), terminalRecoveryRecord(kind))
576			writeLegacyLog(t, dir2, entries2...)
577			q2, err := Open(dir2)
578			if err != nil {
579				t.Fatalf("valid %s terminal fixture must open: %v", kind, err)
580			}
581			if r := statusOf(t, q2, "t"); r.Status != StatusReplay || r.Attempts != 1 {
582				t.Fatalf("valid %s terminal fixture restored wrong: %+v", kind, r)
583			}
584			q2.Close()
585		}
586	}
