				q.Close()
			}
			t.Fatalf("%s: want ErrCorrupt, got %v", name, err)
		}
		if q != nil {
			t.Fatalf("%s: no usable queue", name)
		}
		got, _ := os.ReadFile(path)
		if string(got) != string(data) {
			t.Fatalf("%s: file modified", name)
		}
		t.Logf("%s error: %v", name, err)
	}

	// 5. torn final: source frame missing 2 bytes -> opens, source absent.
	torn := append([]byte(logMagic), ver...)
	torn = append(torn, src[:len(src)-2]...)
	dir := t.TempDir()
	path := filepath.Join(dir, logName)
	if err := os.WriteFile(path, torn, 0o600); err != nil {
		t.Fatal(err)
	}
	q, err := Open(dir)
	if err != nil {
		t.Fatalf("torn tail should open: %v", err)
	}
	if q.sources["a"] {
		t.Fatal("torn source record must be dropped")
	}
	if fi, _ := os.Stat(path); fi.Size() != int64(len(logMagic)+len(ver)) {
		t.Fatalf("tail not truncated: %d", fi.Size())
	}
	q.Close()

	// 6. good log with source opens and keeps it.
	good := append([]byte(logMagic), ver...)
	good = append(good, src...)
	dir = t.TempDir()
	path = filepath.Join(dir, logName)
	if err := os.WriteFile(path, good, 0o600); err != nil {
		t.Fatal(err)
	}
	q, err = Open(dir)
	if err != nil {
		t.Fatalf("good log should open: %v", err)
	}
	if !q.sources["a"] {
		t.Fatal("source lost")
	}
	q.Close()

	// 7. zero-length version record wording.
	zv := append([]byte(logMagic), 0, 0, 0, 0)
	dir = t.TempDir()
	_ = os.WriteFile(filepath.Join(dir, logName), zv, 0o600)
	_, err = Open(dir)
	if !strings.Contains(err.Error(), "zero-length version record at offset") {
		t.Fatalf("unexpected wording: %v", err)
	}

	// 8. declared length enormous -> incomplete version wording carries n.
	hdr := make([]byte, 4)
	binary.BigEndian.PutUint32(hdr, 1_000_000)
	huge := append([]byte(logMagic), hdr...)
	huge = append(huge, 1, 2, 3)
	dir = t.TempDir()
	_ = os.WriteFile(filepath.Join(dir, logName), huge, 0o600)
	_, err = Open(dir)
	if !strings.Contains(err.Error(), "length 1000000 but only 3 body/checksum bytes present") {
		t.Fatalf("unexpected wording: %v", err)
	}
}
